() => {
  const input = document.getElementById('twotabsearchtextbox');
  if (input) {
    input.focus();
    input.value = 'black stroller';
    const event = new KeyboardEvent('keydown', { key: 'Enter', code: 'Enter', keyCode: 13, which: 13, bubbles: true });
    input.dispatchEvent(event);
    const form = input.closest('form');
    if (form) form.submit();
    return 'submitted via form';
  }
  return 'input not found';
}

() => {
  const products = [];
  // Look at product cards in the search results
  const cards = document.querySelectorAll('div[data-component-type="s-search-result"]');
  cards.forEach(card => {
    const title = card.querySelector('h2')?.textContent?.trim() || '';
    const ratingEl = card.querySelector('span[aria-label*="out of 5 stars"]');
    const rating = ratingEl?.getAttribute('aria-label') || '';
    const reviewsEl = card.querySelector('a[aria-label*="ratings"]') || card.querySelector('span[aria-label*="reviews"]');
    const reviews = reviewsEl?.textContent?.trim() || '';
    const priceEl = card.querySelector('span.a-price > span.a-offscreen');
    const price = priceEl?.textContent?.trim() || '';
    const asin = card.getAttribute('data-asin') || '';
    const url = asin ? `https://www.amazon.com/dp/${asin}` : '';
    if (title) products.push({title, rating, reviews, price, asin, url});
  });
  return JSON.stringify(products);
}

