() => {
  const data = __data('Product');
  if (!data) return 'no product data';
  const out = [];
  for (let i = 0; i < data.length; i++) {
    const p = data[i];
    const r = p.aggregateRating || {};
    const o = p.offers || {};
    out.push({
      name: (p.name || '').substring(0, 80),
      ratingValue: r.ratingValue,
      reviewCount: r.reviewCount,
      ratingCount: r.ratingCount,
      price: o.price || o.lowPrice,
      color: p.color,
      url: p.url || ''
    });
  }
  return JSON.stringify(out);
}

() => {
  const cards = document.querySelectorAll('div[data-component-type="s-search-result"]');
  const products = [];
  cards.forEach(card => {
    const titleEl = card.querySelector('h2 span') || card.querySelector('h2');
    const title = titleEl ? titleEl.textContent.trim() : '';
    const ratingEl = card.querySelector('span[aria-label*="out of 5 stars"]');
    let rating = '';
    let reviewCount = '';
    if (ratingEl) {
      const label = ratingEl.getAttribute('aria-label') || '';
      rating = label;
      const m = label.match(/by\s+([\d,]+)/i);
      if (m) reviewCount = m[1];
    }
    const reviewLink = card.querySelector('a[aria-label*="ratings"]');
    if (reviewLink) {
      const t = reviewLink.getAttribute('aria-label') || reviewLink.textContent;
      const numMatch = t.match(/[\d,]+/);
      if (numMatch) reviewCount = numMatch[0];
    }
    const priceEl = card.querySelector('span.a-price > span.a-offscreen');
    const price = priceEl ? priceEl.textContent.trim() : '';
    const asin = card.getAttribute('data-asin') || '';
    if (title) {
      products.push(title.substring(0, 80) + ' | rating=' + rating + ' | reviews=' + reviewCount + ' | price=' + price + ' | asin=' + asin);
    }
  });
  return products.length + ' products found:\n' + products.join('\n');
}

