() => {
  // Get the search results cards
  const cards = document.querySelectorAll('div[data-component-type="s-search-result"]');
  const out = [];
  cards.forEach((c, idx) => {
    const title = c.querySelector('h2')?.textContent?.trim() || '';
    const ratingEl = c.querySelector('span[aria-label*="out of 5 stars"]');
    const ratingLabel = ratingEl?.getAttribute('aria-label') || '';
    const reviewLink = c.querySelector('a[aria-label*="ratings"]');
    const reviewLabel = reviewLink?.getAttribute('aria-label') || '';
    const price = c.querySelector('span.a-price > span.a-offscreen')?.textContent?.trim() || '';
    const asin = c.getAttribute('data-asin') || '';
    out.push(idx + ': ' + title.substring(0, 50) + ' | r=' + ratingLabel + ' | rev=' + reviewLabel + ' | $=' + price + ' | asin=' + asin);
  });
  return out.join('\n');
}

