() => {
  // Find all rating review links and their counts
  const cards = document.querySelectorAll('div[data-component-type="s-search-result"]');
  const out = [];
  cards.forEach((c, idx) => {
    const title = c.querySelector('h2')?.textContent?.trim() || '';
    const reviewLink = c.querySelector('a[aria-label*="ratings"]');
    let reviewCount = '';
    if (reviewLink) {
      const label = reviewLink.getAttribute('aria-label') || '';
      reviewCount = label;
    }
    const ratingEl = c.querySelector('span[aria-label*="out of 5 stars"]');
    const rating = ratingEl ? ratingEl.getAttribute('aria-label') : '';
    out.push({idx, title: title.substring(0, 60), rating, reviewCount});
  });
  return JSON.stringify(out);
}
